package com.eduflow.controller;
import com.eduflow.dto.PortalDtos.*; import com.eduflow.entity.*; import com.eduflow.security.*; import com.eduflow.service.*; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/parents") @RequiredArgsConstructor @PreAuthorize("hasRole('USER')")
public class ParentController {
 private final ParentPortalService parents; private final CenterMembershipService memberships;
 private Long center(){Long id=CurrentCenterContext.get();if(id==null)throw new com.eduflow.exception.EduFlowException(HttpStatus.BAD_REQUEST,"tenant.context.required");return id;}
 @PostMapping("/links") public ResponseEntity<Map<String,Long>> link(@AuthenticationPrincipal AuthenticatedUser principal,@Valid @RequestBody ParentLinkRequest request){Long c=center();memberships.assertRoleForUserId(principal.id(),c,Role.CENTER_ADMIN);memberships.assertRoleForUserId(request.parentUserId(),c,Role.PARENT);ParentStudentLink link=parents.link(c,request.parentUserId(),request.studentId(),principal.id());return ResponseEntity.status(201).body(Map.of("id",link.getId()));}
 @DeleteMapping("/links/{linkId}") public ResponseEntity<Void> unlink(@AuthenticationPrincipal AuthenticatedUser principal,@PathVariable Long linkId){Long c=center();memberships.assertRoleForUserId(principal.id(),c,Role.CENTER_ADMIN);parents.unlink(c,linkId,principal.id());return ResponseEntity.noContent().build();}
 @GetMapping("/accounts") public List<ParentAccountOption> parentAccounts(@AuthenticationPrincipal AuthenticatedUser principal){Long c=center();memberships.assertRoleForUserId(principal.id(),c,Role.CENTER_ADMIN);return parents.listParentAccounts(c);}
 @GetMapping("/links") public List<ParentLinkResponse> listLinks(@AuthenticationPrincipal AuthenticatedUser principal){Long c=center();memberships.assertRoleForUserId(principal.id(),c,Role.CENTER_ADMIN);return parents.listLinks(c);}
 @GetMapping("/children") public List<ChildResponse> children(@AuthenticationPrincipal AuthenticatedUser principal){Long c=center();memberships.assertRoleForUserId(principal.id(),c,Role.PARENT);return parents.children(c,principal.id());}
 @GetMapping("/children/{studentId}/grades") public List<ParentGradeResponse> grades(@AuthenticationPrincipal AuthenticatedUser principal,@PathVariable Long studentId){Long c=center();memberships.assertRoleForUserId(principal.id(),c,Role.PARENT);return parents.grades(c,principal.id(),studentId);}
 @GetMapping("/children/{studentId}/attendance") public List<ParentAttendanceResponse> attendance(@AuthenticationPrincipal AuthenticatedUser principal,@PathVariable Long studentId){Long c=center();memberships.assertRoleForUserId(principal.id(),c,Role.PARENT);return parents.attendance(c,principal.id(),studentId);}
}
